use super::*;
use crate::{inventory::Item,smithing_catalyst::{Config as Catalyst,Profile},variables::{Varp,Varbit,Transmit}};
const PROFILES:[(i32,i32,i32,i32,f64);4]=[(2353,440,2,30,17.5),(2359,447,4,50,30.0),(2361,449,6,70,37.5),(2363,451,8,85,50.0)];
fn prepared(index:usize,coal:usize,cats:usize,stored:Option<i32>)->(World,ActorId,Arc<Request>){
 let(bar,ore,required,level,xp)=PROFILES[index];let mut w=World::default();w.collision.allocate(3200,3200,0);w.smithing=Some(Config{queue:900,skill:13,max_level:99,xp_rate:1.0,tutorial:None});w.smithing_catalyst=Some(Catalyst{item:27017,coal:453,profiles:PROFILES.into_iter().map(|(bar,ore,coal,level,xp)|(bar,Profile{ore,coal,level,xp})).collect()});let bag=crate::coal_bag::Config{closed:12019,open:24480,coal:453,capes:[9795,9796,13280],base:Varp{id:65531,permanent:true,transmit:Transmit::Never,bit_protect:true,client_code:-1},stored:Varbit{base:65531,lsb:25,msb:30}};w.coal_bag=Some(bag);w.object_types.stackable.extend([12019,24480]);let mut stats=Stats::default();stats.set_base(13,99);stats.set_current(13,99);let mut p=PlayerData::new(1,"Catalyst furnace".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);p.inventory.restore_slot(0,Some(Item{id:ore,count:1,vars:0})).unwrap();for slot in 1..=coal{p.inventory.restore_slot(slot,Some(Item{id:453,count:1,vars:0})).unwrap();}for slot in 20..20+cats{p.inventory.restore_slot(slot,Some(Item{id:27017,count:1,vars:0})).unwrap();}if stored.is_some(){p.inventory.restore_slot(27,Some(Item{id:24480,count:1,vars:0})).unwrap();}p.variables.set(bag.base,0x81000001u32 as i32,false);p.variables.set_bit(bag.base,bag.stored,stored.unwrap_or(0),false).unwrap();w.queue_login(1,p).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,true).unwrap();w.drain_events();(w,a,Arc::new(Request{product:bar,produced:1,consumed:vec![(ore,1),(453,required)],xp,animation:899,cycles:5,impurity:false,members:false,repeat_delay:None,required_level:level,required_tools:vec![]}))
}
fn amount(w:&World,a:ActorId,id:i32)->i32{crate::smithing_make::total(&w.data(a).unwrap().inventory,&w.object_types,id)}
fn stored(w:&World,a:ActorId)->i32{w.data(a).unwrap().variables.bit(w.coal_bag.unwrap().stored).unwrap()}
fn finish(w:&mut World,n:usize){for _ in 0..n{w.tick().unwrap();}}
#[test]
fn smithing_catalyst_four_recipe_physical_virtual_matrix_consumes_one_and_doubles_last_xp(){
 for index in 0..4{let(bar,ore,base_coal,_,xp)=PROFILES[index];for physical in [0,base_coal/2,base_coal]{for bag in [None,Some(0),Some(base_coal/2),Some(36)]{for cats in 0..=1{let(mut w,a,r)=prepared(index,physical as usize,cats,bag);let needed=if cats==1{base_coal/2}else{base_coal};let made=physical+bag.unwrap_or(0)>=needed;w.start_smelting(a,r,1).unwrap();finish(&mut w,6);let spent=if made{needed}else{0};let physical_spent=physical.min(spent);assert_eq!(amount(&w,a,453),physical-physical_spent);assert_eq!(stored(&w,a),bag.unwrap_or(0)-(spent-physical_spent));assert_eq!(amount(&w,a,27017),cats as i32-i32::from(cats==1&&made));assert_eq!(amount(&w,a,ore),i32::from(!made));assert_eq!(amount(&w,a,bar),i32::from(made));assert_eq!(w.data(a).unwrap().stats.fine_xp(13),if made{(xp*if cats==1{2.0}else{1.0}*10.0)as i32}else{0});assert_eq!(w.data(a).unwrap().variables.get(65531)as u32&!(63<<25),0x81000001);}}}}
}
#[test]
fn smithing_catalyst_ice_uniform_gloves_never_replace_or_preserve_a_consumable(){
 for gloves in [false,true]{for catalyst in [false,true]{let(mut w,a,r)=prepared(3,8,usize::from(catalyst),None);if gloves{w.data_mut(a).unwrap().equipment.restore_slot(9,Some(Item{id:27031,count:1,vars:0})).unwrap();}let equipment=w.data(a).unwrap().equipment.clone();w.start_smelting(a,r,1).unwrap();finish(&mut w,6);assert_eq!(amount(&w,a,27017),0);assert_eq!(amount(&w,a,453),if catalyst{4}else{0});assert_eq!(amount(&w,a,2363),1);assert_eq!(w.data(a).unwrap().stats.fine_xp(13),if catalyst{1000}else{500});assert_eq!(w.data(a).unwrap().equipment,equipment);}}
}
#[test]
fn smithing_catalyst_repeats_retain_base_recipe_then_fall_back_after_last_consumable(){
 for virtual_second in [false,true]{let(mut w,a,r)=prepared(0,if virtual_second{1}else{5},if virtual_second{2}else{1},Some(if virtual_second{1}else{0}));w.data_mut(a).unwrap().inventory.restore_slot(18,Some(Item{id:440,count:1,vars:0})).unwrap();w.start_smelting(a,r,5).unwrap();finish(&mut w,5);assert_eq!(amount(&w,a,2353),1);assert_eq!(w.data(a).unwrap().stats.fine_xp(13),350);finish(&mut w,12);assert_eq!(amount(&w,a,2353),2);assert_eq!(amount(&w,a,440),0);assert_eq!(amount(&w,a,27017),0);assert_eq!(amount(&w,a,453),if virtual_second{0}else{2});assert_eq!(stored(&w,a),0);assert_eq!(w.data(a).unwrap().stats.fine_xp(13),if virtual_second{700}else{525});assert!(!w.player(a).unwrap().queues.contains(900));}
 let(mut w,a,r)=prepared(0,5,1,Some(0));w.data_mut(a).unwrap().inventory.restore_slot(18,Some(Item{id:440,count:1,vars:0})).unwrap();w.start_smelting(a,r,5).unwrap();finish(&mut w,5);w.submit(a,Action::CoalBagItem{slot:27,item:24480,operation:4}).unwrap();finish(&mut w,12);assert_eq!(amount(&w,a,2353),1);assert_eq!(amount(&w,a,453),4);assert_eq!(w.data(a).unwrap().stats.fine_xp(13),350);
}
#[test]
fn smithing_catalyst_late_consumable_membership_and_level_use_current_authority(){
 for case in 0..6{let(mut w,a,r)=prepared(3,8,if case==1{0}else{1},None);w.start_smelting(a,r,1).unwrap();w.tick().unwrap();match case{0=>{w.data_mut(a).unwrap().inventory.restore_slot(20,None).unwrap();},1=>{w.data_mut(a).unwrap().inventory.restore_slot(20,Some(Item{id:27017,count:1,vars:0})).unwrap();},2=>w.set_membership(a,false).unwrap(),3=>w.data_mut(a).unwrap().stats.set_current(13,84),4=>{w.data_mut(a).unwrap().inventory.restore_slot(20,Some(Item{id:27017,count:2,vars:0})).unwrap();},_=>{w.data_mut(a).unwrap().inventory.restore_slot(20,Some(Item{id:27017,count:1,vars:7})).unwrap();}}
 finish(&mut w,5);let made=case!=3;let boost=case==1;assert_eq!(amount(&w,a,2363),i32::from(made));assert_eq!(amount(&w,a,453),if !made{8}else if boost{4}else{0});assert_eq!(w.data(a).unwrap().stats.fine_xp(13),if !made{0}else if boost{1000}else{500});assert_eq!(amount(&w,a,27017),match case{0|1=>0,4=>2,_=>1});}
}
#[test]
fn smithing_catalyst_failed_material_xp_storage_or_life_cannot_leak_spending_or_reward(){
 for case in 0..8{let(mut w,a,r)=prepared(3,0,1,Some(36));w.start_smelting(a,r,1).unwrap();w.tick().unwrap();match case{0=>{w.data_mut(a).unwrap().inventory.restore_slot(0,None).unwrap();},1=>{w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:451,count:2,vars:0})).unwrap();},2=>w.smithing.as_mut().unwrap().xp_rate=f64::INFINITY,3=>w.coal_bag.as_mut().unwrap().base.id=65530,4=>w.players.get_mut(a.slot as usize).unwrap().death_queued=true,5=>w.data_mut(a).unwrap().stats.set_current(3,0),6=>w.players.get_mut(a.slot as usize).unwrap().pending_logout=true,_=>{w.data_mut(a).unwrap().inventory.restore_slot(27,None).unwrap();}}
 let before=w.data(a).unwrap().clone();finish(&mut w,5);if let Ok(after)=w.data(a){assert_eq!(after.inventory,before.inventory,"case{case}");assert_eq!(after.stats,before.stats);assert_eq!(after.variables.get(65531),before.variables.get(65531));}assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::SmithingProductMade{..}|WorldEvent::SkillAdvanced{..})));}
}
#[test]
fn smithing_catalyst_selection_uses_discounted_cost_without_caching_it_in_the_job(){
 for catalyst in [false,true]{let(mut w,a,_)=prepared(0,1,usize::from(catalyst),None);let types=[(440,"Iron ore"),(453,"Coal"),(2353,"Steel bar"),(27017,"Smithing catalyst")].into_iter().map(|(id,name)|(id,crate::smelting::ItemType{name:name.into(),certificate:false,placeholder:false})).collect();let recipe=crate::smelting::Recipe{bar:2353,label:"Steel".into(),level:30,xp:17.5,ingredients:vec![(440,1),(453,2)],impurity:false,members:false,repeat_delay:None};let p=w.data(a).unwrap();let selected=recipe.select_with_catalyst(&p.inventory,&w.object_types,&types,&p.stats,13,899,1,w.coal_bag,&p.variables,true,w.smithing_catalyst.as_ref()).unwrap();match selected{crate::smelting::Selection::Start{request,count}=>{assert!(catalyst);assert_eq!(request.consumed,[(440,1),(453,2)]);assert_eq!(request.xp,17.5);w.start_smelting(a,request,count).unwrap();finish(&mut w,6);assert_eq!(amount(&w,a,2353),1);assert_eq!(w.data(a).unwrap().stats.fine_xp(13),350);},crate::smelting::Selection::Denied(_)=>assert!(!catalyst)}}
}
#[test]
fn smithing_catalyst_doubles_base_once_before_character_and_global_rates(){
 for(rate,global,expected)in[(100,1.0,1000),(500,1.0,5000),(250,1.0,2500),(500,2.0,10000)]{let(mut w,a,r)=prepared(3,8,1,None);w.data_mut(a).unwrap().xp_rate_hundreds=rate;w.smithing.as_mut().unwrap().xp_rate=global;w.start_smelting(a,r,1).unwrap();finish(&mut w,6);assert_eq!(w.data(a).unwrap().stats.fine_xp(13),expected);assert_eq!(amount(&w,a,2363),1);assert_eq!(amount(&w,a,27017),0);assert_eq!(amount(&w,a,453),4);}
}
